spec.setup_code:
var PER = 14, N = 5, gam = 0.8, lam = 1.003, eta = 1.5;
var INK = '#04204B', SEC = '#3D5F91', FAINT = '#8098BC', BLUE = '#0B4FC0', WARM = '#B4552F', VIO = '#6A47C2';
var eps = [0.5, -0.7, 0.8, -0.6, 0.7];
var sig = [], sh = [], sn = [], xs = [0.7], xh = [], xe = [], xn = [];
for (var i = 0; i < N; i++) {
  sig[i] = Math.pow(0.7, i);
  sh[i] = sig[i] * (1 + gam);
  sn[i] = sig[i] * 0.7;
  xh[i] = xs[i] + lam * Math.sqrt(sh[i] * sh[i] - sig[i] * sig[i]) * 0.4 * eps[i];
  var dir = xh[i] / sh[i];
  xe[i] = xh[i] + (sn[i] - sh[i]) * dir;
  xn[i] = xh[i] + eta * (sn[i] - sh[i]) * dir;
  xs[i + 1] = xn[i];
}
var T = [{ c0: 0.4, c1: 3, d0: 3.5, d1: 4.3, e0: 4.6, e1: 6, h0: 6.6, h1: 8.2 }];
for (var k = 1; k < N; k++) {
  var s0 = 8.7 + 1.2 * (k - 1);
  T[k] = { c0: s0, c1: s0 + 0.4, d0: s0 + 0.35, d1: s0 + 0.5, e0: s0 + 0.4, e1: s0 + 0.65, h0: s0 + 0.6, h1: s0 + 1.1 };
}
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function ease(u) { return u * u * (3 - 2 * u); }
function prog(t, a, b) { return ease(clamp((t - a) / (b - a), 0, 1)); }
function lerp(a, b, f) { return a + (b - a) * f; }

function draw(ctx, w, h, time, dt) {
  ctx.globalAlpha = 1;
  ctx.setLineDash([]);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, w, h);
  var t = time % PER;
  var A = Math.min(1, t / 0.4, (PER - t) / 0.4);
  ctx.globalAlpha = A;
  ctx.textBaseline = 'alphabetic';

  var pl = Math.round(Math.max(42, w * 0.09)), pr = w - 46, pt = 46, pb = h - 62;
  var pw = pr - pl;
  function X(u) { return pl + (u + 0.45) / 1.65 * pw; }
  function Y(s) { return pt + (Math.log(2.4) - Math.log(s)) / (Math.log(2.4) - Math.log(0.1)) * (pb - pt); }
  function label(str, x, y, align, col, size) {
    var sz = size || 12;
    ctx.font = sz + 'px sans-serif';
    var tw = ctx.measureText(str).width;
    if (tw > w - 12 && sz > 11) { sz = 11; ctx.font = sz + 'px sans-serif'; tw = ctx.measureText(str).width; }
    var left = align === 'center' ? x - tw / 2 : (align === 'right' ? x - tw : x);
    left = clamp(left, 6, Math.max(6, w - 6 - tw));
    ctx.fillStyle = col;
    ctx.textAlign = 'left';
    ctx.fillText(str, left, y);
  }
  function head(x, y, ang, col) {
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 9 * Math.cos(ang - 0.4), y - 9 * Math.sin(ang - 0.4));
    ctx.lineTo(x - 9 * Math.cos(ang + 0.4), y - 9 * Math.sin(ang + 0.4));
    ctx.closePath();
    ctx.fill();
  }
  function arrow(a, b, p, col, lw, dash) {
    var ex = lerp(a[0], b[0], p), ey = lerp(a[1], b[1], p);
    ctx.strokeStyle = col; ctx.lineWidth = lw;
    ctx.setLineDash(dash || []);
    ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(ex, ey); ctx.stroke();
    ctx.setLineDash([]);
    if (p > 0.05) head(ex, ey, Math.atan2(b[1] - a[1], b[0] - a[0]), col);
  }
  function jagged(a, b, p, col) {
    var dx = b[0] - a[0], dy = b[1] - a[1], L = Math.sqrt(dx * dx + dy * dy) || 1;
    var nx = -dy / L, ny = dx / L, m = Math.max(2, Math.floor(16 * p));
    ctx.strokeStyle = col; ctx.lineWidth = 2;
    ctx.beginPath();
    for (var j = 0; j <= m; j++) {
      var f = p * j / m, o = (j > 0 && j < m) ? (j % 2 ? 6 : -6) : 0;
      var px = a[0] + dx * f + nx * o, py = a[1] + dy * f + ny * o;
      if (j === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();
    if (p > 0.05) head(a[0] + dx * p, a[1] + dy * p, Math.atan2(dy, dx), col);
  }
  function pts(j) {
    return { p0: [X(xs[j]), Y(sig[j])], p1: [X(xh[j]), Y(sh[j])], p2: [X(xe[j]), Y(sn[j])], p3: [X(xn[j]), Y(sn[j])] };
  }

  // active step
  var ka = 0;
  for (var q = N - 1; q > 0; q--) { if (t >= T[q].c0) { ka = q; break; } }
  var tm = T[ka], P = pts(ka);
  var cp = prog(t, tm.c0, tm.c1), dp = prog(t, tm.d0, tm.d1), ep = prog(t, tm.e0, tm.e1), hp = prog(t, tm.h0, tm.h1);

  // grid and axes
  var ticks = [0.1, 0.2, 0.5, 1, 2];
  ctx.font = '11px sans-serif';
  for (var g = 0; g < ticks.length; g++) {
    var gy = Y(ticks[g]);
    ctx.globalAlpha = A * 0.25; ctx.strokeStyle = FAINT; ctx.lineWidth = 1; ctx.setLineDash([2, 4]);
    ctx.beginPath(); ctx.moveTo(pl, gy); ctx.lineTo(pr, gy); ctx.stroke();
    ctx.setLineDash([]); ctx.globalAlpha = A;
    ctx.fillStyle = SEC; ctx.textAlign = 'right';
    ctx.fillText(String(ticks[g]), pl - 6, gy + 4);
  }
  ctx.strokeStyle = FAINT; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(pl, pt - 4); ctx.lineTo(pl, pb); ctx.lineTo(pr, pb); ctx.stroke();
  ctx.save(); ctx.translate(14, (pt + pb) / 2); ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = SEC; ctx.font = '12px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('σ (log scale)', 0, 0); ctx.restore();
  label('position x  (clean data at left, noisy at right)', (pl + pr) / 2, pb + 20, 'center', SEC, 12);

  // clean band
  ctx.fillStyle = 'rgba(11,79,192,0.10)';
  ctx.fillRect(X(-0.04), pt, X(0.04) - X(-0.04), pb - pt);
  label('clean data', X(0), pt + 12, 'center', BLUE, 11);

  // dot position
  var dot;
  if (t < tm.c0) dot = P.p0;
  else if (t < tm.h0) dot = [lerp(P.p0[0], P.p1[0], cp), lerp(P.p0[1], P.p1[1], cp)];
  else dot = [lerp(P.p1[0], P.p3[0], hp), lerp(P.p1[1], P.p3[1], hp)];

  // sigma bar
  var xb = pr + 10, ys = P.p0[1];
  ctx.strokeStyle = FAINT; ctx.lineWidth = 1;
  ctx.strokeRect(xb, pt, 10, pb - pt);
  ctx.fillStyle = SEC;
  var gtop = Math.max(dot[1], ys);
  ctx.fillRect(xb, gtop, 10, pb - gtop);
  if (dot[1] < ys - 0.5) { ctx.fillStyle = WARM; ctx.fillRect(xb, dot[1], 10, ys - dot[1]); }
  label('σ', xb + 5, pt - 8, 'center', INK, 12);
  ctx.globalAlpha = A * 0.4; ctx.strokeStyle = FAINT; ctx.setLineDash([2, 3]);
  ctx.beginPath(); ctx.moveTo(dot[0], dot[1]); ctx.lineTo(xb, dot[1]); ctx.stroke();
  ctx.setLineDash([]); ctx.globalAlpha = A;
  if (ys - dot[1] > 6) {
    label('σ̂', xb + 14, dot[1] + 4, 'left', WARM, 12);
    label('σᵢ', xb + 14, ys + 4, 'left', SEC, 11);
  }

  // trail of finished steps
  for (var j = 0; j < ka; j++) {
    var Q = pts(j);
    ctx.globalAlpha = A * 0.55;
    ctx.strokeStyle = WARM; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(Q.p0[0], Q.p0[1]); ctx.lineTo(Q.p1[0], Q.p1[1]); ctx.stroke();
    ctx.strokeStyle = BLUE; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(Q.p1[0], Q.p1[1]); ctx.lineTo(Q.p3[0], Q.p3[1]); ctx.stroke();
    ctx.fillStyle = INK;
    ctx.beginPath(); ctx.arc(Q.p0[0], Q.p0[1], 3, 0, 6.2832); ctx.fill();
    ctx.globalAlpha = A;
  }
  // ring at start of active step
  ctx.strokeStyle = INK; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.arc(P.p0[0], P.p0[1], 7, 0, 6.2832); ctx.stroke();

  // direction line
  if (dp > 0) {
    ctx.globalAlpha = A * (1 - 0.6 * hp);
    arrow(P.p1, [X(0.05), P.p1[1]], dp, VIO, 1.5, [3, 3]);
    if (ka === 0 && dp > 0.7) label('(x̂ − D)/σ̂', (P.p1[0] + X(0)) / 2, P.p1[1] - 8, 'center', VIO, 12);
    ctx.globalAlpha = A;
  }
  // churn jump
  if (cp > 0) jagged(P.p0, P.p1, cp, WARM);
  // Euler and AF3 steps
  if (ep > 0) arrow(P.p1, P.p2, ep, FAINT, 2, [6, 4]);
  if (hp > 0) arrow(P.p1, P.p3, hp, BLUE, 2.6);
  if (ep >= 1) {
    ctx.strokeStyle = FAINT; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(P.p2[0], P.p2[1], 5, 0, 6.2832); ctx.stroke();
    if (ka === 0) label('xᵢ+1 (η = 1)', P.p2[0], P.p2[1] - 12, 'center', SEC, 12);
  }
  if (hp >= 1) {
    ctx.strokeStyle = BLUE; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(P.p3[0], P.p3[1], 9, 0, 6.2832); ctx.stroke();
    if (ka === 0) label('xᵢ+1 (η = 1.5)', P.p3[0], P.p3[1] + 24, 'center', BLUE, 12);
  }

  // D dot
  ctx.fillStyle = BLUE; ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(X(0), dot[1], 6, 0, 6.2832); ctx.fill(); ctx.stroke();
  label(ka === 0 ? 'D(x̂; σ̂)' : 'D', X(0) - 11, dot[1] + 4, 'right', BLUE, 12);
  // current point
  ctx.fillStyle = INK;
  ctx.beginPath(); ctx.arc(dot[0], dot[1], 5.5, 0, 6.2832); ctx.fill();
  if (ka === 0) {
    if (t < tm.c1) label(cp < 0.5 ? 'xᵢ' : 'x̂', dot[0] + 10, dot[1] - 8, 'left', INK, 12);
    else if (hp < 0.05) label('x̂', dot[0], dot[1] - 12, 'center', INK, 12);
  }

  // phase caption (top centre)
  var cap;
  if (ka === 0) {
    if (t < tm.c0) cap = 'Current noisy point xᵢ at noise level σᵢ';
    else if (t < tm.c1 + 0.2) cap = 'Churn: σ̂ = σᵢ(1 + γ), add fresh noise';
    else if (t < tm.e0) cap = 'Direction (x̂ − D)/σ̂ points at the prediction D';
    else if (t < tm.h0) cap = 'Plain Euler step, η = 1 (dashed)';
    else cap = 'AF3 step, η = 1.5: 1.5× further toward D';
  } else {
    cap = 'Repeat: churn, then step 1.5×. Zig-zag down in σ (i = ' + ka + ')';
  }
  label(cap, w / 2, 24, 'center', INK, 13);

  // status line
  var st = 'i = ' + ka + '   σᵢ = ' + sig[ka].toFixed(2);
  if (t >= tm.c0) st += ' → σ̂ = ' + sh[ka].toFixed(2);
  if (t >= tm.e0) st += ' → σᵢ+1 = ' + sn[ka].toFixed(2);
  label(st, w / 2, h - 16, 'center', SEC, 12);
  ctx.globalAlpha = 1;
  return;
}

return { draw: draw };
